import test from 'node:test';import assert from 'node:assert/strict';import {FORM_ERROR_LABELS,FORM_ERROR_CASES,assertFormErrors,assertFormUpgrades} from './catalogue-form-errors.mjs';
const rows=()=>[320,1280].flatMap(width=>Object.keys(FORM_ERROR_LABELS).flatMap(lang=>FORM_ERROR_CASES.map(kind=>({width,lang,kind,status:'passed',error:FORM_ERROR_LABELS[lang][kind],roundTrip:true,preserved:true,associated:true,fits:true,notSubmitted:true,iconClear:true,invalidVisual:true,painted:true}))));
test('form errors require66 unique rows and reject stale text, lost answers/association and submission',()=>{assert.doesNotThrow(()=>assertFormErrors(rows()));assert.throws(()=>assertFormErrors(rows().slice(1)));const dup=rows();dup[1]=dup[0];assert.throws(()=>assertFormErrors(dup));for(const key of ['roundTrip','preserved','associated','fits','notSubmitted','iconClear','invalidVisual','painted']){const bad=rows();bad[0][key]=false;assert.throws(()=>assertFormErrors(bad));}const bad=rows();bad[0].error=FORM_ERROR_LABELS.en.missing;assert.throws(()=>assertFormErrors(bad));});
test('offline upgrade requires both widths, exact old/new cached modules and both offline languages',()=>{const good=[320,1280].map(width=>({width,status:'passed',originStopped:true,baseFormExact:true,headFormExact:true,headLoaderExact:true,headErrorStyleExact:true,offlineLanguages:['pl','uk']}));assert.doesNotThrow(()=>assertFormUpgrades(good));assert.doesNotThrow(()=>assertFormUpgrades([],false));assert.throws(()=>assertFormUpgrades(good,false));for(const key of ['originStopped','baseFormExact','headFormExact','headLoaderExact','headErrorStyleExact']){const bad=structuredClone(good);bad[0][key]=false;assert.throws(()=>assertFormUpgrades(bad));}assert.throws(()=>assertFormUpgrades(good.slice(1)));});
